const inbound = $('Workflow Input').item.json;
const cfg = $('Load Business Config').item.json;
const ctx = $('Load Order Context').item.json;
const ex = $('Extract Order Details').item.json.output || {};
const resolved = $('Resolve Products').item.json.resolved || [];
const lang = ex.language === 'en' ? 'en' : 'bn';
const L = function (b, e) { return lang === 'bn' ? b : e; };
const bnd = '০১২৩৪৫৬৭৮৯';
const nd = function (s) { return String(s || '').replace(/[০-৯]/g, function (d) { return String(bnd.indexOf(d)); }); };
const fmt = function (n) { return String(Math.round(Number(n) * 100) / 100); };
const sig = function (arr) { return arr.map(function (i) { return i.product_id + 'x' + i.qty; }).sort().join(','); };

const settings = {};
(ctx.settings || []).forEach(function (s) { settings[s.k] = s.v; });
const draft = (ctx.draft_items || []).map(function (i) {
  return { product_id: i.product_id, sku: i.sku, name: i.name, size_ml: i.size_ml, unit_price: Number(i.unit_price), qty: Number(i.qty) };
});

const issues = [];
const okNew = [];
resolved.forEach(function (r) {
  const qty = Number(r.quantity) || 1;
  const m = r.matches || [];
  if (!Number.isInteger(qty) || qty < 1 || qty > 10) {
    issues.push(L('পরিমাণ ১ থেকে ১০ এর মধ্যে হতে হবে', 'Quantity must be between 1 and 10'));
    return;
  }
  if (m.length === 0) {
    issues.push(L('"' + r.query + '" নামে কোনো পণ্য খুঁজে পাইনি', 'I could not find "' + r.query + '"'));
    return;
  }
  if (m.length > 1) {
    const opts = m.map(function (p) { return p.product_name + (p.size_ml ? ' ' + p.size_ml + 'ml' : '') + ' (' + fmt(p.price_bdt) + ' টাকা)'; }).join(', ');
    issues.push(L('"' + r.query + '" এর কোনটি চান? ', 'Which "' + r.query + '" do you want? ') + opts);
    return;
  }
  const p = m[0];
  if (Number(p.stock_quantity) < qty) {
    issues.push(L(p.product_name + ' এই পরিমাণে স্টকে নেই', p.product_name + ' is not available in that quantity'));
    return;
  }
  okNew.push({ product_id: p.product_id, sku: p.sku, name: p.product_name, size_ml: p.size_ml, unit_price: Number(p.price_bdt), qty: qty });
});

let items = draft.map(function (i) { return Object.assign({}, i); });
if (ex.message_type === 'change_items' && okNew.length > 0) {
  items = okNew;
} else {
  okNew.forEach(function (n) {
    const found = items.find(function (i) { return i.product_id === n.product_id; });
    if (found) { found.qty = Math.min(10, found.qty + n.qty); } else { items.push(n); }
  });
}

const normPhone = function (s) {
  let d = nd(s).replace(/[^0-9]/g, '');
  if (d.indexOf('880') === 0) d = '0' + d.slice(3);
  return d;
};
let name = ctx.customer_name || '';
let phone = ctx.phone || '';
let address = ctx.address || '';
let detailsChanged = false;
if (ex.name && ex.name.trim().length >= 2) {
  if (ex.name.trim() !== name) detailsChanged = true;
  name = ex.name.trim();
}
if (ex.phone && ex.phone.trim()) {
  const p = normPhone(ex.phone);
  if (/^01[3-9][0-9]{8}$/.test(p)) { if (p !== phone) detailsChanged = true; phone = p; }
  else issues.push(L('মোবাইল নম্বরটি সঠিক নয় (১১ ডিজিটের নম্বর দিন)', 'The mobile number looks invalid (use an 11-digit number)'));
}
if (ex.address && ex.address.trim()) {
  const a = ex.address.trim();
  if (a.length >= 12) { if (a !== address) detailsChanged = true; address = a; }
  else issues.push(L('ঠিকানাটি অসম্পূর্ণ, এলাকা ও থানা/জেলা সহ লিখুন', 'The address is incomplete, please include area and district'));
}

const hasDraft = !!ctx.draft_order_id;
const type = ex.message_type;
const T = {
  handover: L(
    'আপনার বার্তার জন্য ধন্যবাদ। বিষয়টি আমাদের টিমকে জানানো হয়েছে, একজন প্রতিনিধি শীঘ্রই আপনার সাথে যোগাযোগ করবেন।',
    'Thank you for your message. I have passed this to our team and a representative will contact you shortly.'
  )
};
const issueText = issues.length ? issues.join('. ') + '. ' : '';
const lines = items.map(function (i) {
  return '• ' + i.name + (i.size_ml ? ' ' + i.size_ml + 'ml' : '') + ' × ' + i.qty + ' = ' + fmt(i.unit_price * i.qty) + ' টাকা';
}).join('\n');

let action = 'none';
let orderState = ctx.order_state;
let step = '';
let reply = '';
let needsHuman = false;
const reasons = [];
let delivery = 0;
const subtotal = items.reduce(function (s, i) { return s + i.unit_price * i.qty; }, 0);
let total = subtotal;

if (type === 'cancel') {
  if (hasDraft) {
    action = 'cancel'; step = 'cancel';
    reply = L('আপনার অর্ডারটি বাতিল করা হয়েছে। নতুন অর্ডার করতে চাইলে জানাবেন।', 'Your order has been cancelled. Let us know if you would like to order again.');
  } else {
    step = 'nothing_to_cancel';
    reply = L('বাতিল করার মতো কোনো চলমান অর্ডার পাইনি।', 'I could not find an active order to cancel.');
  }
} else if (type === 'question') {
  needsHuman = true; reasons.push('question during order flow');
} else if (items.length === 0) {
  step = 'ask_items';
  reply = issueText + L('কোন পণ্যটি অর্ডার করতে চান? পণ্যের নাম ও পরিমাণ জানাবেন।', 'Which product would you like to order? Please share the product name and quantity.');
} else {
  const missing = [];
  if (!name) missing.push(L('নাম', 'name'));
  if (!phone) missing.push(L('মোবাইল নম্বর', 'mobile number'));
  if (!address) missing.push(L('সম্পূর্ণ ঠিকানা', 'full delivery address'));
  if (missing.length > 0) {
    step = 'ask_details'; action = 'save'; orderState = 'draft';
    reply = issueText + L('আপনার অর্ডারে আছে:\n', 'Your order so far:\n') + lines + '\n' +
      L('অর্ডার সম্পূর্ণ করতে অনুগ্রহ করে জানান: ', 'To complete the order please share: ') + missing.join(', ');
  } else {
    const addrL = address.toLowerCase();
    const inDhaka = addrL.indexOf('dhaka') >= 0 || address.indexOf('ঢাকা') >= 0;
    const feeRaw = inDhaka ? settings.delivery_fee_inside_dhaka : settings.delivery_fee_outside_dhaka;
    const hasFee = !(feeRaw === undefined || feeRaw === null || String(feeRaw).trim() === '' || isNaN(Number(feeRaw)));
    if (!hasFee) {
      needsHuman = true; reasons.push('delivery fee setting missing');
    } else {
      delivery = Number(feeRaw);
      total = subtotal + delivery;
      const itemsChanged = sig(items) !== sig(draft);
      if (type === 'confirm' && ctx.order_state === 'awaiting_confirmation' && !itemsChanged && !detailsChanged && issues.length === 0) {
        action = 'confirm'; step = 'confirm'; orderState = 'confirmed';
      } else {
        step = 'summary'; action = 'save'; orderState = 'awaiting_confirmation';
        reply = issueText + L('আপনার অর্ডারের সারসংক্ষেপ:\n', 'Your order summary:\n') + lines + '\n' +
          L('সাবটোটাল: ', 'Subtotal: ') + fmt(subtotal) + L(' টাকা\nডেলিভারি চার্জ: ', ' BDT\nDelivery charge: ') + fmt(delivery) +
          L(' টাকা\nমোট: ', ' BDT\nTotal: ') + fmt(total) + L(' টাকা (ক্যাশ অন ডেলিভারি)\n', ' BDT (cash on delivery)\n') +
          L('নাম: ', 'Name: ') + name + L('\nমোবাইল: ', '\nMobile: ') + phone + L('\nঠিকানা: ', '\nAddress: ') + address + '\n\n' +
          L('অর্ডার নিশ্চিত করতে "হ্যাঁ" লিখুন। পরিবর্তন করতে জানান, বাতিল করতে "বাতিল" লিখুন।', 'Reply "yes" to confirm your order. Tell us if you want to change anything, or reply "cancel" to cancel.');
      }
    }
  }
}

if (needsHuman) { action = 'handover'; step = 'handover'; reply = T.handover; }

const et = Number(inbound.event_time || 0);
const withinWindow = !et || (Date.now() - et) < 23 * 3600 * 1000;
let blockReason = '';
if (!cfg.graph_api_version) blockReason = 'META_GRAPH_API_VERSION not configured';
else if (inbound.platform === 'instagram' && !cfg.ig_user_id) blockReason = 'IG_USER_ID not configured';
else if (ctx.consent_status === 'revoked') blockReason = 'customer revoked consent';
else if (!withinWindow) blockReason = 'outside 24h messaging window';

const payload = {
  action: action,
  customer_id: ctx.customer_id,
  conversation_id: ctx.conversation_id,
  draft_order_id: ctx.draft_order_id || '',
  order_state: orderState,
  name: name,
  phone: phone,
  address: address,
  subtotal: subtotal,
  delivery_fee: delivery,
  total: total,
  platform: inbound.platform,
  items: items.map(function (i) { return Object.assign({}, i, { line_total: i.unit_price * i.qty }); }),
  idempotency_key: 'msg-' + ctx.message_id
};

return { json: {
  platform: inbound.platform,
  page_id: inbound.page_id,
  sender_id: inbound.sender_id,
  webhook_event_id: inbound.webhook_event_id || 0,
  conversation_id: ctx.conversation_id,
  message_id: ctx.message_id,
  lang: lang,
  step: step,
  action: action,
  reply: reply,
  needs_human: needsHuman,
  handover_text: T.handover,
  reasons: reasons,
  total: total,
  message_excerpt: String(inbound.message_text || '').slice(0, 120),
  can_send: blockReason === '',
  block_reason: blockReason,
  payload_json: JSON.stringify(payload)
} };

const d = $('Decide Order Step').item.json;
const r = $input.first().json;
const L = function (b, e) { return d.lang === 'bn' ? b : e; };
let reply = d.reply;
let needsHuman = d.needs_human;
let alertAdmin = d.needs_human;
let alertText = d.needs_human ? 'Human needed (order flow, ' + d.platform + '). Conversation ID: ' + d.conversation_id + '. Reason: ' + (d.reasons.join('; ') || 'customer request') + '. Message: ' + d.message_excerpt : '';
const fmt = function (n) { return String(Math.round(Number(n) * 100) / 100); };
if (d.action === 'confirm') {
  if (r.confirmed_order_id) {
    reply = L(
      'ধন্যবাদ! আপনার অর্ডার নিশ্চিত হয়েছে। অর্ডার আইডি: ' + r.confirmed_order_id + '। মোট: ' + fmt(d.total) + ' টাকা (ক্যাশ অন ডেলিভারি)। আমাদের টিম শীঘ্রই যোগাযোগ করবে।',
      'Thank you! Your order is confirmed. Order ID: ' + r.confirmed_order_id + '. Total: ' + fmt(d.total) + ' BDT (cash on delivery). Our team will contact you shortly.'
    );
    alertAdmin = true;
    alertText = 'New COD order ' + r.confirmed_order_id + ' (' + d.platform + '), total ' + fmt(d.total) + ' BDT. Review it in the orders table.';
  } else {
    needsHuman = true;
    alertAdmin = true;
    reply = d.handover_text;
    alertText = 'Order confirmation failed (stock or status changed). Conversation ID: ' + d.conversation_id + '. Please check manually.';
  }
}
return { json: {
  platform: d.platform,
  page_id: d.page_id,
  sender_id: d.sender_id,
  webhook_event_id: d.webhook_event_id,
  conversation_id: d.conversation_id,
  message_id: d.message_id,
  intent: 'order',
  final_reply: reply,
  needs_human: needsHuman,
  can_send: d.can_send,
  block_reason: d.block_reason,
  alert_admin: alertAdmin,
  alert_text: alertText,
  order_id: r.confirmed_order_id || r.order_id || null
} };

parameters.query:
WITH o AS (
  INSERT INTO messages (conversation_id, platform, direction, sender_id, message_text, intent, processing_status, platform_message_id)
  VALUES ($1::bigint, $2::text, 'outbound', $3::text, $4::text, $5::text, 'sent', NULLIF($6::text, ''))
  ON CONFLICT (platform, platform_message_id, direction) WHERE platform_message_id IS NOT NULL DO NOTHING
  RETURNING message_id
), i AS (
  UPDATE messages SET intent = $5::text,
    processing_status = CASE WHEN $9::boolean THEN 'escalated' ELSE 'processed' END
  WHERE message_id = $7::bigint RETURNING message_id
), w AS (
  UPDATE webhook_events SET processing_status = 'processed', processed_at = now() WHERE id = $8::bigint RETURNING id
)
SELECT (SELECT message_id FROM o) AS outbound_message_id;

WITH o AS (
  INSERT INTO messages (conversation_id, platform, direction, sender_id, message_text, intent, processing_status)
  VALUES ($1::bigint, $2::text, 'outbound', $3::text, $4::text, $5::text, 'failed')
  RETURNING message_id
), i AS (
  UPDATE messages SET intent = $5::text, processing_status = 'failed' WHERE message_id = $6::bigint RETURNING message_id
), w AS (
  UPDATE webhook_events SET processing_status = 'failed', processed_at = now(), error_message = $8::text WHERE id = $7::bigint RETURNING id
)
SELECT (SELECT message_id FROM o) AS outbound_message_id;
